const scoreboard = $('Fetch NBA Scoreboard').first().json;
const odds = $('Fetch Live Odds').all().map(i => i.json);
const history = $('Fetch Historical Data').all().map(i => i.json);

// Build game analysis for each matchup
const games = Array.isArray(odds) ? odds : [odds];

const analyses = games.map(game => {
  const homeTeam = game.home_team;
  const awayTeam = game.away_team;
  const commence = game.commence_time;

  // Extract best odds across bookmakers
  const bookmakers = game.bookmakers || [];
  let bestSpreadHome = null;
  let bestSpreadBook = '';
  let bestTotalOver = null;
  let bestTotalBook = '';
  let bestMoneylineHome = null;
  let bestMlBook = '';

  for (const book of bookmakers) {
    for (const market of (book.markets || [])) {
      if (market.key === 'spreads') {
        const homeOutcome = (market.outcomes || []).find(o => o.name === homeTeam);
        if (homeOutcome && (!bestSpreadHome || homeOutcome.price > bestSpreadHome.price)) {
          bestSpreadHome = homeOutcome;
          bestSpreadBook = book.title;
        }
      }
      if (market.key === 'totals') {
        const overOutcome = (market.outcomes || []).find(o => o.name === 'Over');
        if (overOutcome && (!bestTotalOver || overOutcome.price > bestTotalOver.price)) {
          bestTotalOver = overOutcome;
          bestTotalBook = book.title;
        }
      }
      if (market.key === 'h2h') {
        const homeOutcome = (market.outcomes || []).find(o => o.name === homeTeam);
        if (homeOutcome && (!bestMoneylineHome || homeOutcome.price > bestMoneylineHome.price)) {
          bestMoneylineHome = homeOutcome;
          bestMlBook = book.title;
        }
      }
    }
  }

  // Calculate consensus line from average of all books
  let spreadSum = 0, spreadCount = 0;
  let totalSum = 0, totalCount = 0;
  for (const book of bookmakers) {
    for (const market of (book.markets || [])) {
      if (market.key === 'spreads') {
        const ho = (market.outcomes || []).find(o => o.name === homeTeam);
        if (ho) { spreadSum += ho.point; spreadCount++; }
      }
      if (market.key === 'totals') {
        const ov = (market.outcomes || []).find(o => o.name === 'Over');
        if (ov) { totalSum += ov.point; totalCount++; }
      }
    }
  }

  const consensusSpread = spreadCount ? (spreadSum / spreadCount).toFixed(1) : null;
  const consensusTotal = totalCount ? (totalSum / totalCount).toFixed(1) : null;

  // Check historical model accuracy for these teams
  const relevantHistory = history.filter(h =>
    h.home_team === homeTeam || h.away_team === awayTeam ||
    h.home_team === awayTeam || h.away_team === homeTeam
  );
  const pastPicks = relevantHistory.filter(h => h.outcome);
  const wins = pastPicks.filter(h => h.outcome === 'win').length;
  const winRate = pastPicks.length ? ((wins / pastPicks.length) * 100).toFixed(1) : 'N/A';

  return {
    game_id: game.id,
    home_team: homeTeam,
    away_team: awayTeam,
    commence_time: commence,
    consensus_spread: consensusSpread,
    consensus_total: consensusTotal,
    best_spread: bestSpreadHome ? { point: bestSpreadHome.point, price: bestSpreadHome.price, book: bestSpreadBook } : null,
    best_total_over: bestTotalOver ? { point: bestTotalOver.point, price: bestTotalOver.price, book: bestTotalBook } : null,
    best_moneyline_home: bestMoneylineHome ? { price: bestMoneylineHome.price, book: bestMlBook } : null,
    bookmaker_count: bookmakers.length,
    historical_win_rate: winRate + '%',
    historical_sample_size: pastPicks.length
  };
});

return analyses.map(a => ({ json: a }));
